# Generated by build.py from recipe.yml for recipe tftp-move-a-firmware-fetch-to-http. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'firmware images' > site/readme.txt
head -c 1300 /dev/urandom > site/firmware.bin
head -c 1024 /dev/urandom > site/exact.bin
surl --directory site tftp://127.0.0.1:8080/ http://127.0.0.1:8080/ &
sleep 1
curl -s -o over-tftp.bin tftp://127.0.0.1:8080/firmware.bin -o over-http.bin http://127.0.0.1:8080/firmware.bin && cmp over-tftp.bin over-http.bin && echo identical
kill $(jobs -p)
